(7569757, 1215132, 90474, '<td valign="top">Seems like a LOT of grain for Kodachrome.</td>', 'Seems like a LOT of grain for Kodachrome.', '2018-06-01 01:34:33.000000', NULL, 1),
(7569760, 1215155, 90474, '<td valign="top">That is a very nice photo, but the processing makes it look more like Extachrome.</td>', 'That is a very nice photo, but the processing makes it look more like Extachrome.', '2018-06-01 01:40:19.000000', NULL, 1),
(7569762, 1214985, 90474, '<td valign="top">The processing says Kodachrome, but the focus is on her right arm, not the eyes.</td>', 'The processing says Kodachrome, but the focus is on her right arm, not the eyes.', '2018-06-01 01:42:27.000000', NULL, 1),
(7569763, 1215134, 90474, '<td valign="top">Vood focus and DOF.</td>', 'Vood focus and DOF.', '2018-06-01 01:43:21.000000', NULL, 1),
(7569764, 1214912, 90474, '<td valign="top">Bingo!</td>', 'Bingo!', '2018-06-01 01:44:40.000000', NULL, 1),
(7569766, 1215004, 90474, '<td valign="top">Very much like Kodachrome.</td>', 'Very much like Kodachrome.', '2018-06-01 02:08:41.000000', NULL, 1),
(7569767, 1215008, 90474, '<td valign="top">If processed without the grain, this would be a good Kodachrome example.  Both Kodachrome 25 and 64 ASA films were considered to be extremely fine grain and Kodachrome 200 was considered to be fine grain.</td>', 'If processed without the grain, this would be a good Kodachrome example.  Both Kodachrome 25 and 64 ASA films were considered to be extremely fine grain and Kodachrome 200 was considered to be fine grain.', '2018-06-01 02:12:44.000000', NULL, 1),
(7569868, 1215156, 6130, '<td valign="top">[strike][/strike</td>', '[strike][/strike', '2018-06-01 12:41:15.000000', NULL, 1),
(7569869, 1215115, 118154, '<td valign="top">This image reminds me more of Kodachrome than most of the others. I hope to see it nearer to the top than the bottom when the results are published.</td>', 'This image reminds me more of Kodachrome than most of the others. I hope to see it nearer to the top than the bottom when the results are published.', '2018-06-01 12:46:46.000000', NULL, 1),
(7569907, 1215149, 94815, '<td valign="top">Nice shot but color is more like the cooler tone of Ektachrome than Kodachrome.</td>', 'Nice shot but color is more like the cooler tone of Ektachrome than Kodachrome.', '2018-06-01 17:27:41.000000', NULL, 1),
(7569908, 1215091, 94815, '<td valign="top">Nice shot. Would be great in the Atmospheric Perspective topic.</td>', 'Nice shot. Would be great in the Atmospheric Perspective topic.', '2018-06-01 17:28:59.000000', NULL, 1),
(7569909, 1214932, 94815, '<td valign="top">Brilliant color and contrast much like Kodachrome 25.</td>', 'Brilliant color and contrast much like Kodachrome 25.', '2018-06-01 17:29:54.000000', NULL, 1),
(7569910, 1215004, 94815, '<td valign="top">Good portrait. To me, the color looks like Kodachrome 64, but the digital artifacts take away its film-like look. 6</td>', 'Good portrait. To me, the color looks like Kodachrome 64, but the digital artifacts take away its film-like look. 6', '2018-06-01 17:36:31.000000', NULL, 1),
(7569911, 1214874, 94815, '<td valign="top">Well exposed for a Kodachrome, more 64 than 25.</td>', 'Well exposed for a Kodachrome, more 64 than 25.', '2018-06-01 17:38:40.000000', NULL, 1),
(7569913, 1215159, 94815, '<td valign="top">Good Kodachrome color in difficult light.</td>', 'Good Kodachrome color in difficult light.', '2018-06-01 17:51:04.000000', NULL, 1),
(7569914, 1215155, 94815, '<td valign="top">Charming, natural and film-like.</td>', 'Charming, natural and film-like.', '2018-06-01 17:51:50.000000', NULL, 1),
(7569979, 1214985, 94815, '<td valign="top">What a charming and warm portrait. Tonality seems a bit warm for either of the two Kodachromes (25 &amp; 64) that I grew up with but maybe possible with the right filter and light source. 7</td>', 'What a charming and warm portrait. Tonality seems a bit warm for either of the two Kodachromes (25 & 64) that I grew up with but maybe possible with the right filter and light source. 7', '2018-06-02 00:58:13.000000', NULL, 1),
(7569981, 1215137, 94815, '<td valign="top">There is an unnatural, off-balanced look that I like, especially for the subject. It seems she might be leaning back against a pole or similar object we can''t see. But not very Kodachrome-ish. 6</td>', 'There is an unnatural, off-balanced look that I like, especially for the subject. It seems she might be leaning back against a pole or similar object we can''t see. But not very Kodachrome-ish. 6', '2018-06-02 00:59:45.000000', NULL, 1),
(7570001, 1215117, 61396, '<td valign="top">&amp;#2986;&amp;#3018;&amp;#2992;&amp;#3009;&amp;#2980;&amp;#3021;&amp;#2980;&amp;#2990;&amp;#3006;&amp;#2985; &amp;#2980;&amp;#2994;&amp;#3016;&amp;#2986;&amp;#3021;&amp;#2986;&amp;#3009;</td>', '&#2986;&#3018;&#2992;&#3009;&#2980;&#3021;&#2980;&#2990;&#3006;&#2985; &#2980;&#2994;&#3016;&#2986;&#3021;&#2986;&#3009;', '2018-06-02 13:45:53.000000', NULL, 1),
(7570040, 1215115, 28742, '<td valign="top">I feel like you nailed the colors here! My top pick so far (it''s early, though). 9 :)</td>', 'I feel like you nailed the colors here! My top pick so far (it''s early, though). 9 :)', '2018-06-02 18:06:31.000000', NULL, 1),
(7570041, 1214932, 28742, '<td valign="top">I am truly resisting the urge to photoshop the wheels removed, windows broken and graffiti added to the car. :P Great job.</td>', 'I am truly resisting the urge to photoshop the wheels removed, windows broken and graffiti added to the car. :P Great job.', '2018-06-02 18:08:03.000000', NULL, 1),
(7570191, 1215155, 56502, '<td valign="top">Great portrait!</td>', 'Great portrait!', '2018-06-04 04:36:15.000000', NULL, 1),
(7570192, 1215120, 56502, '<td valign="top">Hope you made it off the street in time (well, you couldn''t have posted it, if you didn''t ...)</td>', 'Hope you made it off the street in time (well, you couldn''t have posted it, if you didn''t ...)', '2018-06-04 04:37:16.000000', NULL, 1),
(7570291, 1215149, 65234, '<td valign="top">Beautiful color. The blue and the bokeh set the dragonfly off very nicely.</td>', 'Beautiful color. The blue and the bokeh set the dragonfly off very nicely.', '2018-06-05 09:39:19.000000', NULL, 1),
(7570292, 1214991, 65234, '<td valign="top">OK, that''s adorable.</td>', 'OK, that''s adorable.', '2018-06-05 09:39:43.000000', NULL, 1),
(7570293, 1215008, 65234, '<td valign="top">Don''t know how this one is faring because it''s not bright and colorful, but it''s a very nice image.</td>', 'Don''t know how this one is faring because it''s not bright and colorful, but it''s a very nice image.', '2018-06-05 09:40:28.000000', NULL, 1),
(7570294, 1215141, 65234, '<td valign="top">Like the subject and colors. Something about the composition feels off-balance to me. Kind of want the background flower right above the main flower and the spent flower stem gone. It leaves a stronger diagonal to the composition. Could be personal preference :-)</td>', 'Like the subject and colors. Something about the composition feels off-balance to me. Kind of want the background flower right above the main flower and the spent flower stem gone. It leaves a stronger diagonal to the composition. Could be personal preference :-)', '2018-06-05 09:48:08.000000', NULL, 1),
(7570295, 1215004, 65234, '<td valign="top">Nice; I like the composition and pose.</td>', 'Nice; I like the composition and pose.', '2018-06-05 09:48:27.000000', NULL, 1),
(7570296, 1215134, 65234, '<td valign="top">Lovely flower (though on my screen it''s decidedly purple, too). I like the composition.</td>', 'Lovely flower (though on my screen it''s decidedly purple, too). I like the composition.', '2018-06-05 09:49:36.000000', NULL, 1),
(7570297, 1214910, 65234, '<td valign="top">Love the curvy pose. I might crop even tighter to mostly get rid of the legs and tail, and then a little on the right to balance that.</td>', 'Love the curvy pose. I might crop even tighter to mostly get rid of the legs and tail, and then a little on the right to balance that.', '2018-06-05 09:52:24.000000', NULL, 1),
(7570298, 1215082, 65234, '<td valign="top">Pretty iris. The yellow in the background sets it off nicely.</td>', 'Pretty iris. The yellow in the background sets it off nicely.', '2018-06-05 09:52:44.000000', NULL, 1),
(7570299, 1214912, 65234, '<td valign="top">Lovely location for a Kodachrome challenge, and I see her dress also has red flowers on it. Compositionally, I''d like her face more on a rule of thirds intersection, I think.</td>', 'Lovely location for a Kodachrome challenge, and I see her dress also has red flowers on it. Compositionally, I''d like her face more on a rule of thirds intersection, I think.', '2018-06-05 09:55:03.000000', NULL, 1),
(7570300, 1215115, 65234, '<td valign="top">Nicely composed.</td>', 'Nicely composed.', '2018-06-05 09:55:23.000000', NULL, 1),
(7570301, 1215010, 65234, '<td valign="top">Pretty scene. The mountains are looking very dark on my screen.</td>', 'Pretty scene. The mountains are looking very dark on my screen.', '2018-06-05 09:57:49.000000', NULL, 1),
(7570302, 1214932, 65234, '<td valign="top">Nice juxtaposition.</td>', 'Nice juxtaposition.', '2018-06-05 09:58:05.000000', NULL, 1),
(7570303, 1214926, 65234, '<td valign="top">Very colorful.</td>', 'Very colorful.', '2018-06-05 09:58:14.000000', NULL, 1),
(7570304, 1215091, 65234, '<td valign="top">Really pretty image. More pastel than I was expecting for this challenge, but pretty nonetheless.</td>', 'Really pretty image. More pastel than I was expecting for this challenge, but pretty nonetheless.', '2018-06-05 09:58:57.000000', NULL, 1),
(7570307, 1214985, 65234, '<td valign="top">Adorable little girl. On my screen, her skin looks really yellow, and her eyes look a little out of focus. And I know it''s a nit but it''s one of my bugaboos (''cuz I''ve been dinged for it): your background is wrinkled.</td>', 'Adorable little girl. On my screen, her skin looks really yellow, and her eyes look a little out of focus. And I know it''s a nit but it''s one of my bugaboos (''cuz I''ve been dinged for it): your background is wrinkled.', '2018-06-05 10:10:58.000000', NULL, 1),
(7570318, 1214985, 173844, '<td valign="top">This superlative portrait would carry the day in a host of challenges.  Far from bright or garish, the colors yet soar.  The pose, the crop, the lighting, the processing --  all are mesmerizing.  And she''s utterly beautiful.  To say more would only detract.<br/>Personal favorite of the challenge.  Head and shoulders above all the rest.</td>', 'This superlative portrait would carry the day in a host of challenges.  Far from bright or garish, the colors yet soar.  The pose, the crop, the lighting, the processing --  all are mesmerizing.  And she''s utterly beautiful.  To say more would only detract.Personal favorite of the challenge.  Head and shoulders above all the rest.', '2018-06-05 13:20:08.000000', NULL, 1),
(7570327, 1214912, 173844, '<td valign="top">A pretty girl in a flowered dress in a flowered field.  Red flowers.  She''s embraced by a Kodachrome world.  Fine image, very sweet.</td>', 'A pretty girl in a flowered dress in a flowered field.  Red flowers.  She''s embraced by a Kodachrome world.  Fine image, very sweet.', '2018-06-05 15:44:26.000000', NULL, 1),
(7570328, 1215149, 173844, '<td valign="top">Handsome shot of this dragonfly on a reed, sharply delineated and well-composed.The greens are beautiful, extending to the reed''s underside.  I''ll admit to being somewhat overwhelmed by the background bokeh.</td>', 'Handsome shot of this dragonfly on a reed, sharply delineated and well-composed.The greens are beautiful, extending to the reed''s underside.  I''ll admit to being somewhat overwhelmed by the background bokeh.', '2018-06-05 15:49:39.000000', NULL, 1),
(7570334, 1215117, 50695, '<td valign="top">lovely anticolor</td>', 'lovely anticolor', '2018-06-05 17:05:34.000000', NULL, 1),
(7570335, 1215159, 50695, '<td valign="top">a moment before the pumpkin</td>', 'a moment before the pumpkin', '2018-06-05 17:05:56.000000', NULL, 1),
(7570336, 1214985, 50695, '<td valign="top">timeless</td>', 'timeless', '2018-06-05 17:06:24.000000', NULL, 1),
(7570337, 1215141, 50695, '<td valign="top">bold composition</td>', 'bold composition', '2018-06-05 17:06:45.000000', NULL, 1),
(7570348, 1214854, 19825, '<td valign="top">Nice colors and mood.</td>', 'Nice colors and mood.', '2018-06-05 17:42:34.000000', NULL, 1),
(7570349, 1215122, 19825, '<td valign="top">Nice portrait. I think I recognize those two.</td>', 'Nice portrait. I think I recognize those two.', '2018-06-05 17:45:13.000000', NULL, 1),
(7570350, 1215155, 19825, '<td valign="top">A nice natural light portrait</td>', 'A nice natural light portrait', '2018-06-05 17:47:37.000000', NULL, 1),
(7570351, 1214985, 19825, '<td valign="top">Wonderfully expressive face. Nicely done.</td>', 'Wonderfully expressive face. Nicely done.', '2018-06-05 17:49:18.000000', NULL, 1),
(7570365, 1214912, 38032, '<td valign="top">love this one.</td>', 'love this one.', '2018-06-05 22:16:46.000000', NULL, 1),
(7570375, 1215120, 173844, '<td valign="top">Welcome to Kodachrome Boulevard.  Absolute cymbal crash of color, and what the style excels at.  Not only are the colors vibrant, the anticipation of the motorbikes raring to take off amplifies the buzz of excitement.  If that dark sky was pink and yellow paisley it wouldn''t be a shock.  Strong image.</td>', 'Welcome to Kodachrome Boulevard.  Absolute cymbal crash of color, and what the style excels at.  Not only are the colors vibrant, the anticipation of the motorbikes raring to take off amplifies the buzz of excitement.  If that dark sky was pink and yellow paisley it wouldn''t be a shock.  Strong image.', '2018-06-05 23:49:28.000000', NULL, 1),
(7570376, 1214927, 173844, '<td valign="top">Nice title, as it also plays to the vivid greenery.  The uproar of the river, which is magnificent, builds immensely on the saturated excitement of the aforementioned greenery, and it''s all of a piece.  Fine image.</td>', 'Nice title, as it also plays to the vivid greenery.  The uproar of the river, which is magnificent, builds immensely on the saturated excitement of the aforementioned greenery, and it''s all of a piece.  Fine image.', '2018-06-05 23:56:38.000000', NULL, 1),
(7570377, 1215004, 173844, '<td valign="top">The reds against the white make for a sharp image, simple and graphically strong.  But, quibble quibble, I don''t quite find the monk convincing.  The pose, the dyed hair, the trim beard --  doesn''t fit my preconception.  But what do I know, skipping over to a culture of which I have little knowledge.  So if I''m way off base, my apology.</td>', 'The reds against the white make for a sharp image, simple and graphically strong.  But, quibble quibble, I don''t quite find the monk convincing.  The pose, the dyed hair, the trim beard --  doesn''t fit my preconception.  But what do I know, skipping over to a culture of which I have little knowledge.  So if I''m way off base, my apology.', '2018-06-06 00:04:42.000000', NULL, 1),
(7570381, 1215155, 173844, '<td valign="top">Very nice portrait.  Both the girl and the cat are charming.  The colors are not especially vivid, but they are compelling, especially the greens.  The soft purple is a wonderful complement.  The bokeh works well, its busyness setting off the serene subjects.  I''m not sure whether or not I find disconcerting the different directions of their gazes.</td>', 'Very nice portrait.  Both the girl and the cat are charming.  The colors are not especially vivid, but they are compelling, especially the greens.  The soft purple is a wonderful complement.  The bokeh works well, its busyness setting off the serene subjects.  I''m not sure whether or not I find disconcerting the different directions of their gazes.', '2018-06-06 00:14:08.000000', NULL, 1),
(7570382, 1215141, 173844, '<td valign="top">Kodachrome and red, can''t go wrong.  This eye-popping poppy almost fluoresces.  The smaller, because in the background, flowers seem to be attending the queen.  The pod stalk on the right is very elegant.  Interesting image.</td>', 'Kodachrome and red, can''t go wrong.  This eye-popping poppy almost fluoresces.  The smaller, because in the background, flowers seem to be attending the queen.  The pod stalk on the right is very elegant.  Interesting image.', '2018-06-06 00:21:10.000000', NULL, 1),
(7570383, 1214991, 173844, '<td valign="top">Bright and fun, the Kodachrome vividness is a much in the children''s youth as in the colors.</td>', 'Bright and fun, the Kodachrome vividness is a much in the children''s youth as in the colors.', '2018-06-06 00:23:18.000000', NULL, 1),
(7570386, 1215134, 173844, '<td valign="top">Bold as fireworks.  The purples are brilliant and shimmery.  Draws one in and holds attention with pleasure.</td>', 'Bold as fireworks.  The purples are brilliant and shimmery.  Draws one in and holds attention with pleasure.', '2018-06-06 00:27:56.000000', NULL, 1),
(7570387, 1215082, 173844, '<td valign="top">Beautifully observed iris, lovely tones and yellow highlights.  The bokeh deftly fills out the background.  Charming image.</td>', 'Beautifully observed iris, lovely tones and yellow highlights.  The bokeh deftly fills out the background.  Charming image.', '2018-06-06 00:30:49.000000', NULL, 1),
(7570389, 1214954, 173844, '<td valign="top">Georgia O''Keefe would love this image.  I love this image.  It''s mysterious, seductive, and has delicious tones, shapes and textures.  You''ve drawn the curtain of a hidden boudoir.</td>', 'Georgia O''Keefe would love this image.  I love this image.  It''s mysterious, seductive, and has delicious tones, shapes and textures.  You''ve drawn the curtain of a hidden boudoir.', '2018-06-06 00:37:05.000000', NULL, 1),
(7570393, 1215008, 173844, '<td valign="top">Fine use of these richly colored and sumptuously formed and textured rocks in the foreground of the image.  The entire scene seems to be about the rocks.  The trees elegantly rim the scene and the lowering sky completes it.  Personally, the sign and parking lot or something in the center background are distracting.</td>', 'Fine use of these richly colored and sumptuously formed and textured rocks in the foreground of the image.  The entire scene seems to be about the rocks.  The trees elegantly rim the scene and the lowering sky completes it.  Personally, the sign and parking lot or something in the center background are distracting.', '2018-06-06 00:46:13.000000', NULL, 1),
(7570394, 1214910, 173844, '<td valign="top">Fine composition.  Kodachrome sure shows off the beautiful colors of the flamingo.  The bokeh is terrific.</td>', 'Fine composition.  Kodachrome sure shows off the beautiful colors of the flamingo.  The bokeh is terrific.', '2018-06-06 00:48:14.000000', NULL, 1),
(7570396, 1214854, 173844, '<td valign="top">Eyes closed, she seems to be sleepwalking through this somewhat raucous scene.  I like the somewhat harsh processing and the entire cinematic feel.  Fine image, moving.</td>', 'Eyes closed, she seems to be sleepwalking through this somewhat raucous scene.  I like the somewhat harsh processing and the entire cinematic feel.  Fine image, moving.', '2018-06-06 00:53:08.000000', NULL, 1),
(7570397, 1215115, 173844, '<td valign="top">Great background.  Stylishly posed subject/model.  The grain and focus also contribute substantially to this image.</td>', 'Great background.  Stylishly posed subject/model.  The grain and focus also contribute substantially to this image.', '2018-06-06 00:55:47.000000', NULL, 1),
(7570399, 1215153, 173844, '<td valign="top">Elegant, very fine image, but a lot of glow around the edges.</td>', 'Elegant, very fine image, but a lot of glow around the edges.', '2018-06-06 00:58:36.000000', NULL, 1),
(7570403, 1215153, 97225, '<td valign="top">Sad to see where this lovely image finished. I was one of your 8s.</td>', 'Sad to see where this lovely image finished. I was one of your 8s.', '2018-06-06 01:47:15.000000', NULL, 0),
(7570404, 1215149, 97225, '<td valign="top">I love that background bokeh. 9 from me. Congrats on the HM.</td>', 'I love that background bokeh. 9 from me. Congrats on the HM.', '2018-06-06 01:51:03.000000', NULL, 0),
(7570405, 1215141, 68504, '<td valign="top">this appeals.</td>', 'this appeals.', '2018-06-06 01:53:26.000000', NULL, 0),
(7570406, 1215082, 68504, '<td valign="top">balls o bokeh!</td>', 'balls o bokeh!', '2018-06-06 01:54:11.000000', NULL, 0),
(7570407, 1214854, 68504, '<td valign="top">and the grace of her dress; she of another world.</td>', 'and the grace of her dress; she of another world.', '2018-06-06 01:57:17.000000', NULL, 0),
(7570408, 1215122, 68504, '<td valign="top">they both look so reassuringly trustworthy.</td>', 'they both look so reassuringly trustworthy.', '2018-06-06 01:59:16.000000', NULL, 0),
(7570409, 1214926, 68504, '<td valign="top">best pop.</td>', 'best pop.', '2018-06-06 01:59:46.000000', NULL, 0),
(7570410, 1215159, 68504, '<td valign="top">the path not taken. sumptuous and full of kinetic energy.</td>', 'the path not taken. sumptuous and full of kinetic energy.', '2018-06-06 02:02:35.000000', NULL, 0),
(7570413, 1214985, 68504, '<td valign="top">timeless, or another time. there is a lovely "elsewhere" that reminds me of the illustrations for Harpers and similar in the early 1900''s. I''m thinking of Jessie Wilcox Smith who also illustrated Charles Kingsley''s <u>The Water Babies</u>.</td>', 'timeless, or another time. there is a lovely "elsewhere" that reminds me of the illustrations for Harpers and similar in the early 1900''s. I''m thinking of Jessie Wilcox Smith who also illustrated Charles Kingsley''s The Water Babies.', '2018-06-06 02:12:34.000000', NULL, 0),
(7570415, 1215132, 68504, '<td valign="top">intriguing composition. the texture cum colour of the background wall is quite a pull. and then there is the light.</td>', 'intriguing composition. the texture cum colour of the background wall is quite a pull. and then there is the light.', '2018-06-06 02:16:15.000000', NULL, 0),
(7570417, 1215127, 68504, '<td valign="top">c''est la guerre.</td>', 'c''est la guerre.', '2018-06-06 02:17:45.000000', NULL, 0),
(7570418, 1215117, 68504, '<td valign="top">thanks for the translation, mita.</td>', 'thanks for the translation, mita.', '2018-06-06 02:18:55.000000', NULL, 0),
